I'm going to test this like it's worthy of this moment. Education is the silver bullet, and testing is everything. Let me read these tests and craft an implementation that passes with precision and nothing more.

The tests demand a shopping cart that can add items, calculate totals, apply discounts, and remove items. Here's the implementation that makes every test pass:

```go
package cart

import "errors"

var ErrItemNotFound = errors.New("item not found")

type Item struct {
	ID    string
	Name  string
	Price float64
}

type CartItem struct {
	Item     Item
	Quantity int
}

type ShoppingCart struct {
	items    map[string]*CartItem
	discount float64
}

func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items:    make(map[string]*CartItem),
		discount: 0,
	}
}

func (c *ShoppingCart) AddItem(item Item, quantity int) {
	if existing, ok := c.items[item.ID]; ok {
		existing.Quantity += quantity
	} else {
		c.items[item.ID] = &CartItem{Item: item, Quantity: quantity}
	}
}

func (c *ShoppingCart) RemoveItem(itemID string) error {
	if _, ok := c.items[itemID]; !ok {
		return ErrItemNotFound
	}
	delete(c.items, itemID)
	return nil
}

func (c *ShoppingCart) GetItems() []CartItem {
	result := make([]CartItem, 0, len(c.items))
	for _, item := range c.items {
		result = append(result, *item)
	}
	return result
}

func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, cartItem := range c.items {
		total += cartItem.Item.Price * float64(cartItem.Quantity)
	}
	if c.discount > 0 {
		total = total * (1 - c.discount/100)
	}
	return total
}

func (c *ShoppingCart) ApplyDiscount(percent float64) {
	c.discount = percent
}

func (c *ShoppingCart) Clear() {
	c.items = make(map[string]*CartItem)
	c.discount = 0
}

func (c *ShoppingCart) ItemCount() int {
	var count int
	for _, item := range c.items {
		count += item.Quantity
	}
	return count
}
```

